output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "drop_cart_only_at_parking_mouth",
    "text": "A cart may be left behind only at a wide cart-parking mouth rather than in a shelf aisle or traffic lane.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "cartParkingMouth": {
          "and": [
            "wideAisle",
            {
              "not": "adjShelf"
            },
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            }
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "cartParkingMouth"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "After parking a cart for a cartless aisle excursion, the shopper is obliged to retrieve it before the trip ends.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "cartParkingMouth": {
          "and": [
            "wideAisle",
            {
              "not": "adjShelf"
            },
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            }
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart",
              "cartParkingMouth"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              },
              "cartParkingMouth"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "cartless_excursions_no_horizontal_roaming",
    "text": "Once away from the entrance area, a shopper without a cart is prohibited from travelling horizontally.",
    "abstraction": {
      "state_properties": {
        "entranceCartArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "horizontalMove": {
          "or": [
            "E",
            "W"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          "horizontalMove",
          {
            "not": "entranceCartArea"
          }
        ]
      }
    }
  },
  {
    "id": "cartless_only_in_aisle_excursion_zone",
    "text": "A shopper without a cart may move only in the entrance/cart area, a designated cart-parking mouth, or the adjacent single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "entranceCartArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartParkingMouth": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "adjShelf"
            },
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            }
          ]
        },
        "cartlessAllowedZone": {
          "or": [
            "entranceCartArea",
            "cartParkingMouth",
            "singleFileShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          "MOVE",
          {
            "not": "cartlessAllowedZone"
          }
        ]
      }
    }
  },
  {
    "id": "cartless_service_in_single_file_aisles",
    "text": "Shelf interactions inside single-file shelf aisles must be performed without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "interact_only_at_functional_points",
    "text": "Interactions are allowed only at functional contact points: the cart station, a cart-parking mouth, or a cell adjacent to a shelf.",
    "abstraction": {
      "state_properties": {
        "cartStation": "at(1,7)",
        "cartParkingMouth": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "adjShelf"
            },
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            }
          ]
        },
        "functionalContactPoint": {
          "or": [
            "cartStation",
            "cartParkingMouth",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": "functionalContactPoint"
          }
        ]
      }
    }
  },
  {
    "id": "single_file_aisles_enter_only_from_mouth",
    "text": "Single-file shelf aisles may be entered only from their designated wide cart-parking mouths.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartParkingMouth": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "adjShelf"
            },
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            }
          ]
        }
      },
      "events": {
        "improperSingleFileEntry": {
          "pre": {
            "and": [
              "MOVE",
              {
                "not": "singleFileShelfAisle"
              },
              {
                "not": "cartParkingMouth"
              }
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "improperSingleFileEntry"
    }
  }
]
